import { getPostBySlug, getPosts } from '@/lib/content';
import { notFound } from 'next/navigation';

// Extract headings directly from the rendered HTML string
function extractHeadingsFromHtml(html: string) {
  const regex = /<h([1-3])(?:\s+id="([^"]*)")?[^>]*>(.*?)<\/h\1>/gi;
  const headings = [];
  let match;

  while ((match = regex.exec(html)) !== null) {
    const level = parseInt(match[1], 10);
    // Strip nested tags (like <a>, <code>, <span>) to get plain text
    const text = match[3].replace(/<[^>]+>/g, '').trim();
    // Use the id generated by rehype-slug, or fallback to a slugified version of text
    const id =
      match[2] ||
      text
        .toLowerCase()
        .replace(/[^\w\s-]/g, '')
        .replace(/\s+/g, '-');

    if (text) {
      headings.push({ level, text, id });
    }
  }

  return headings;
}

export default async function NotePage() {
  const posts = await getPosts();
  const defaultSlug = posts[0]?.slug || 'index';
  const note = await getPostBySlug(defaultSlug);

  if (!note) {
    notFound();
  }

  const headings = extractHeadingsFromHtml(note.content);

  return (
    <article className="prose prose-neutral max-w-none">
      <header className="mb-8 border-b border-neutral-200 pb-6">
        <h1 className="text-3xl font-bold tracking-tight mb-2">
          {note.meta.title}
        </h1>
        {note.meta.description && (
          <p className="text-neutral-600 text-lg">{note.meta.description}</p>
        )}
        <div className="flex gap-4 text-sm text-neutral-500 font-sans mt-4">
          {note.meta.date && <span>{note.meta.date}</span>}
          {note.meta.chapter && <span>Chapter {note.meta.chapter}</span>}
        </div>
      </header>

      {/* TABLE OF CONTENTS */}
      {headings.length > 0 && (
        <nav className="my-8 p-6 bg-neutral-100/60 rounded-lg border border-neutral-200/80 font-sans">
          <h2 className="text-base font-semibold text-neutral-900 mb-3 mt-0">
            Table of Contents
          </h2>
          <ul className="space-y-1.5 text-sm list-none p-0 m-0">
            {headings.map((h, i) => (
              <li
                key={i}
                style={{ paddingLeft: `${(h.level - 1) * 1}rem` }}
                className="m-0"
              >
                <a
                  href={`#${h.id}`}
                  className="text-neutral-700 hover:text-blue-600 no-underline hover:underline"
                >
                  {h.text}
                </a>
              </li>
            ))}
          </ul>
        </nav>
      )}

      {/* POST CONTENT */}
      <div dangerouslySetInnerHTML={{ __html: note.content }} />
    </article>
  );
}
